#include <vector>
#include <deque>
#include <algorithm>

class Solution {
public:
    int findMaxValueOfEquation(std::vector<std::vector<int>>& points, int k) {
        std::deque<std::pair<int, int>> q;
        int ans = -2e9;
        for (const auto& p : points) {
            int x = p[0], y = p[1];
            while (!q.empty() && x - q.front().second > k) {
                q.pop_front();
            }
            if (!q.empty()) {
                ans = std::max(ans, q.front().first + y + x);
            }
            int val = y - x;
            while (!q.empty() && q.back().first <= val) {
                q.pop_back();
            }
            q.push_back({val, x});
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int findMaxValueOfEquation(int[][] points, int k) {
        Deque<int[]> q = new ArrayDeque<>();
        int ans = Integer.MIN_VALUE;
        for (int[] p : points) {
            int x = p[0], y = p[1];
            while (!q.isEmpty() && x - q.peekFirst()[1] > k) {
                q.pollFirst();
            }
            if (!q.isEmpty()) {
                ans = Math.max(ans, q.peekFirst()[0] + y + x);
            }
            int val = y - x;
            while (!q.isEmpty() && q.peekLast()[0] <= val) {
                q.pollLast();
            }
            q.offerLast(new int[]{val, x});
        }
        return ans;
    }
}

var findMaxValueOfEquation = function(points, k) {
    const q = [];
    let head = 0;
    let ans = -Infinity;
    for (const [x, y] of points) {
        while (head < q.length && x - q[head][1] > k) {
            head++;
        }
        if (head < q.length) {
            ans = Math.max(ans, q[head][0] + y + x);
        }
        const val = y - x;
        while (q.length > head && q[q.length - 1][0] <= val) {
            q.pop();
        }
        q.push([val, x]);
    }
    return ans;
};
